  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate = typeof definition === 'function' ? undefined : this.compileSchema(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Rejects schema-invalid input as a ToolResponse; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.validatorFor(tool);
    if (!validate(input)) {
      const failures = (validate.errors ?? []).map(describeInputError);
      log.warn('tool', 'input rejected by inputSchema', {name, failures});
      return {result: `Invalid input for tool ${name}: ${failures.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws from register naming the tool when a static inputSchema is not valid JSON Schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'lookup_order',
          description: 'Look up an order',
          inputSchema: {type: 'object', required: 'orderId'},
        },
        async () => 'unreachable'
      )
    ).toThrow(/lookup_order/);
  });

  it('returns a rejection naming the missing required property without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_order',
        description: 'Look up an order',
        inputSchema: {type: 'object', properties: {orderId: {type: 'string'}}, required: ['orderId']},
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_order', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/orderId.*required|required.*orderId/),
    });
  });

  it('validates a function-valued tool against the inputSchema returned for that call', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    let required = 'orderId';
    registry.register(
      () => ({
        name: 'lookup_order',
        description: 'Look up an order',
        inputSchema: {type: 'object', properties: {[required]: {type: 'string'}}, required: [required]},
      }),
      async input => {
        received.push(input);
        return 'found';
      }
    );

    const first = await registry.execute('lookup_order', {orderId: 'A1'});
    required = 'invoiceId';
    const second = await registry.execute('lookup_order', {orderId: 'A1'});

    expect({first: first.result, second: second.result, received}).toEqual({
      first: 'found',
      second: expect.stringMatching(/invoiceId.*required|required.*invoiceId/),
      received: [{orderId: 'A1'}],
    });
  });
});
